<script setup>
import {computed, ref} from 'vue'
import {Layers, Plus, Search, FolderOpen, Pencil, Archive, Files, Clock, CheckCircle2, ArrowRight} from 'lucide-vue-next'
import {statusName, stamp} from '../api'
const props = defineProps({projects: Array, user: Object})
const emit = defineEmits(['create', 'edit', 'archive', 'open'])
const search = ref(''), filter = ref('all')
const rows = computed(() => props.projects.filter(p => (filter.value === 'all' || (filter.value === 'done' ? p.formStatus === 'approved' : p.formStatus !== 'approved')) && `${p.name} ${p.id} ${p.dept} ${p.owner}`.toLowerCase().includes(search.value.toLowerCase())))
</script>
<template>
  <div class="page-header"><div><div class="eyebrow">IP WORKSPACE</div><h1 class="page-title">软著查阅</h1></div><button class="btn btn-primary" @click="emit('create')"><Plus :size="16"/>新建软著项目</button></div>
  <div class="lookup-welcome"><div><div class="kicker">INTELLECTUAL PROPERTY</div><h2>软件著作权工作空间</h2></div><div class="lookup-count"><strong>{{projects.length}}</strong><span>软著项目</span></div></div>
  <div class="grid grid-4"><div class="panel stat" v-for="s in [{name:'项目总量',value:projects.length,icon:Layers},{name:'填报已核实',value:projects.filter(p=>p.formStatus==='approved').length,icon:CheckCircle2},{name:'待管理员核实',value:projects.filter(p=>p.formStatus==='submitted').length,icon:Clock},{name:'附件资料',value:projects.reduce((n,p)=>n+p.fileCount,0),icon:Files}]" :key="s.name"><div class="stat-top">{{s.name}}<span class="stat-icon"><component :is="s.icon" :size="18"/></span></div><div class="stat-value">{{s.value}}</div></div></div>
  <div class="space"></div><section class="panel"><div class="toolbar"><div class="searchbox"><Search :size="16"/><input v-model="search" placeholder="搜索软件名称、编号或负责人" aria-label="搜索项目"/></div><div class="filters"><button v-for="f in [['all','全部项目'],['pending','待完成'],['done','已核实']]" :key="f[0]" class="filter" :class="{active:filter===f[0]}" @click="filter=f[0]">{{f[1]}}</button></div></div>
  <div class="table-scroll"><table class="data-table"><thead><tr><th>软件项目</th><th>归属部门 / 负责人</th><th>填报状态</th><th>附件</th><th>最近更新</th><th>操作</th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td><div class="project-name"><span class="row-avatar"><Layers :size="18"/></span><div><button class="text-link em" @click="emit('open',p.id,'basic')">{{p.name}}</button><div class="muted">{{p.id}} · {{p.version}}</div></div></div></td><td>{{p.dept}}<div class="muted tiny">{{p.owner}}</div></td><td><span class="badge" :class="p.formStatus==='approved'?'positive':p.formStatus==='returned'?'negative':'warning'">{{statusName(p.formStatus)}}</span></td><td>{{p.fileCount}} 份</td><td>{{stamp(p.updated)}}</td><td><div class="actions"><button class="btn btn-sm" @click="emit('open',p.id,'attachments')"><FolderOpen :size="13"/>资料</button><button v-if="user.role==='admin'" class="btn btn-sm icon-btn" title="编辑项目" @click="emit('edit',p)"><Pencil :size="13"/></button><button v-if="user.role==='admin'" class="btn btn-sm icon-btn" title="归档项目" @click="emit('archive',p)"><Archive :size="13"/></button><button class="btn btn-sm btn-soft" @click="emit('open',p.id,'basic')">填报<ArrowRight :size="12"/></button></div></td></tr><tr v-if="!rows.length"><td colspan="6"><div class="empty"><FolderOpen :size="30"/><strong>{{projects.length?'没有匹配的项目':'尚无软著项目'}}</strong><button v-if="!projects.length" class="btn btn-primary" @click="emit('create')">新建软著项目</button></div></td></tr></tbody></table></div></section>
</template>
